57	export interface RawNFItem {
58	  id: number;
59	  nota_id: number;
60	  insumo_id: number | null;
61	  nome_produto: string | null;
62	  quantidade: number | null;
63	  valor_unitario: number | null;
64	  peso_unitario?: number | null;
