90	export function useRecipeGraph(workspaceFichaId?: number | null) {
91	  const [loading, setLoading] = useState(true);
92	  const [fichas, setFichas] = useState<RawFicha[]>([]);
93	  const [items, setItems] = useState<RawItem[]>([]);
94	  const [produtos, setProdutos] = useState<RawProduto[]>([]);
95	  const [insumos, setInsumos] = useState<RawInsumo[]>([]);
96	  const [notas, setNotas] = useState<RawNF[]>([]);
97	  const [nfItems, setNfItems] = useState<RawNFItem[]>([]);
98	  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());
99	
100	  const fetchAll = useCallback(async () => {
101	    setLoading(true);
102	    try {
103	      // 1) Buscar positions DO WORKSPACE ATUAL (cada ficha = seu canvas isolado)
104	      // Se workspaceFichaId não definido, busca só positions de fichas (overview)
105	      const posQuery = supabase
106	        .from('recipe_canvas_positions')
107	        .select('node_type, node_id, x, y, workspace_ficha_id');
108	      const posRes = workspaceFichaId != null
109	        ? await posQuery.eq('workspace_ficha_id', workspaceFichaId)
110	        : await posQuery.eq('node_type', 'ficha');
111	      if (posRes.error) throw posRes.error;
112	      const nfIdsComPosicao = (posRes.data ?? [])
113	        .filter((p: { node_type: string }) => p.node_type === 'nf')
114	        .map((p: { node_id: number }) => p.node_id);
115	
116	      // 2) Buscar tudo em paralelo (incluindo NFs com posição + recentes)
117	      const [fichasRes, itemsRes, insumosRes, nfRecentesRes, nfPositionsRes, nfItemsRes] = await Promise.all([
118	        supabase
119	          .from('fichas_tecnicas')
120	          .select(
121	            'id, nome, custo_calculado, produto_master_id, status, rendimento_quantidade, rendimento_unidade'
122	          )
123	          .neq('status', 'obsoleta')
124	          .order('nome'),
125	        supabase
126	          .from('ficha_tecnica_itens')
127	          .select(
128	            'id, ficha_tecnica_id, produto_master_id, insumo_id, sub_ficha_id, observacao, quantidade, unidade, custo_calculado, preco_unitario_esboco'
129	          ),
130	        supabase
131	          .from('insumos')
132	          .select('id, nome, preco_custo, unidade_compra, unidade_producao, fornecedor_principal, produto_master_id, fator_conversao')
133	          .eq('ativo', true)
134	          .order('nome'),
135	        supabase
136	          .from('notas_fiscais')
137	          .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
138	          .order('data_nota', { ascending: false })
139	          .limit(80),
140	        // NFs antigas que já foram trazidas ao canvas (têm posição)
141	        nfIdsComPosicao.length > 0
142	          ? supabase
143	              .from('notas_fiscais')
144	              .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
145	              .in('id', nfIdsComPosicao)
146	          : Promise.resolve({ data: [], error: null }),
147	        // Itens da NF: todos atrelados a algum insumo (essencial pra preço/edge)
148	        // + itens recentes (display de NFs novas)
149	        supabase
150	          .from('itens_nota_fiscal')
151	          .select('id, nota_id, insumo_id, nome_produto, quantidade, valor_unitario, peso_unitario, unidade_base, unidade')
152	          .or(`insumo_id.not.is.null${nfIdsComPosicao.length > 0 ? `,nota_id.in.(${nfIdsComPosicao.join(',')})` : ''}`)
153	          .order('id', { ascending: false })
154	          .limit(5000),
155	      ]);
156	
157	      if (fichasRes.error) throw fichasRes.error;
158	      if (itemsRes.error) throw itemsRes.error;
159	      if (insumosRes.error) throw insumosRes.error;
160	      if (nfRecentesRes.error) throw nfRecentesRes.error;
161	      if (nfPositionsRes.error) throw nfPositionsRes.error;
162	      if (nfItemsRes.error) throw nfItemsRes.error;
163	
164	      const f = (fichasRes.data ?? []) as RawFicha[];
165	      const i = (itemsRes.data ?? []) as RawItem[];
166	      const ins = (insumosRes.data ?? []) as RawInsumo[];
167	      // Merge NFs recentes + NFs com posição (dedup por id)
168	      const nfRecentes = (nfRecentesRes.data ?? []) as RawNF[];
169	      const nfComPosicao = (nfPositionsRes.data ?? []) as RawNF[];
170	      const nfMap = new Map<number, RawNF>();
171	      nfRecentes.forEach((x) => nfMap.set(x.id, x));
172	      nfComPosicao.forEach((x) => nfMap.set(x.id, x));
173	      const nf = Array.from(nfMap.values());
174	      const nfit = (nfItemsRes.data ?? []) as RawNFItem[];
175	
176	      const pmIds = new Set<number>();
177	      f.forEach((x) => { if (x.produto_master_id) pmIds.add(x.produto_master_id); });
178	      i.forEach((x) => { if (x.produto_master_id) pmIds.add(x.produto_master_id); });
179	
180	      let pms: RawProduto[] = [];
181	      if (pmIds.size > 0) {
182	        const { data, error } = await supabase
183	          .from('produtos_master')
184	          .select('id, nome, codigo_interno, preco_custo, setor')
185	          .in('id', Array.from(pmIds));
186	        if (error) throw error;
187	        pms = (data ?? []) as RawProduto[];
188	      }
189	
190	      const pmap = new Map<string, { x: number; y: number }>();
191	      (posRes.data ?? []).forEach((p: { node_type: string; node_id: number; x: number; y: number }) => {
192	        let key = '';
193	        if (p.node_type === 'ficha') key = fichaNodeId(p.node_id);
194	        else if (p.node_type === 'produto_master') key = produtoNodeId(p.node_id);
195	        else if (p.node_type === 'insumo') key = insumoNodeId(p.node_id);
196	        else if (p.node_type === 'nf') key = nfNodeId(p.node_id);
197	        else if (p.node_type === 'item') key = `item_${p.node_id}`;
198	        if (key) pmap.set(key, { x: Number(p.x), y: Number(p.y) });
199	      });
200	
201	      setFichas(f);
202	      setItems(i);
203	      setProdutos(pms);
204	      setInsumos(ins);
205	      setNotas(nf);
206	      setNfItems(nfit);
207	      setPositions(pmap);
208	    } finally {
209	      setLoading(false);
210	    }
211	  }, [workspaceFichaId]);
212	
213	  useEffect(() => { fetchAll(); }, [fetchAll]);
214	
215	  // Realtime: re-fetch quando algo muda no banco (debounced)
216	  useEffect(() => {
217	    let timer: ReturnType<typeof setTimeout> | null = null;
218	    const debounced = () => {
219	      if (timer) clearTimeout(timer);
220	      timer = setTimeout(() => { fetchAll(); }, 350);
221	    };
222	    const channel = supabase
223	      .channel('recipe_graph_live')
224	      .on('postgres_changes', { event: '*', schema: 'public', table: 'fichas_tecnicas' }, debounced)
225	      .on('postgres_changes', { event: '*', schema: 'public', table: 'ficha_tecnica_itens' }, debounced)
226	      .on('postgres_changes', { event: '*', schema: 'public', table: 'insumos' }, debounced)
227	      .subscribe();
228	    return () => {
229	      if (timer) clearTimeout(timer);
230	      supabase.removeChannel(channel);
231	    };
232	  }, [fetchAll]);
233	
234	  const savePosition = useCallback(async (key: string, x: number, y: number) => {
235	    const parsed = parseNodeId(key);
