255	          updated_at: new Date().toISOString(),
256	        },
257	        { onConflict: 'workspace_ficha_id,node_type,node_id' }
258	      );
259	    if (error) {
260	      console.error('[savePosition] erro:', error, { key, x, y, workspace_ficha_id });
