1	/**
2	 * Modelo de custo de ingrediente — ESPELHO EXATO da função `compute_item_cost`
3	 * do banco (Postgres), que é a fonte da verdade (triggers recomputam custo em
4	 * INSERT/UPDATE/DELETE de ficha_tecnica_itens). O frontend usa isto só para
5	 * EXIBIR custo ao vivo enquanto o usuário edita (antes do trigger persistir).
6	 *
7	 * Regra (igual ao banco):
8	 *   custo_item = preco_custo × quantidade × ratio(unidade_item → unidade_compra)
9	 *   - pares padrão (g↔kg, mL↔L, mg↔g): conversão física; fator_conversao IGNORADO
10	 *   - pares não-padrão (espiga, pack, un…): ratio = 1 / fator_conversao
11	 *   sub-receita: (custo_calculado / rendimento_quantidade) × quantidade
12	 *   esboço:      preco_unitario_esboco × quantidade
13	 */
14	
15	export interface CustoFichaRef {
16	  id: number;
17	  custo_calculado: number;
18	  rendimento_quantidade: number;
19	}
20	
21	interface InsumoCusto {
22	  id: number;
23	  preco_custo: number | null;
24	  unidade_compra?: string | null;
25	  fator_conversao?: number | null;
26	}
27	
28	interface ItemCusto {
29	  insumo_id: number | null;
30	  sub_ficha_id: number | null;
31	  quantidade: number;
32	  unidade: string;
33	  preco_unitario_esboco: number | null;
34	}
35	
36	/** Conversões padrão (físicas) — mesmas do banco. Chave: `${unidadeItem}|${unidadeCompra}`. */
37	const RATIOS_PADRAO: Record<string, number> = {
38	  'g|kg': 0.001,
39	  'kg|g': 1000,
40	  'ml|l': 0.001,
41	  'l|ml': 1000,
42	  'mg|g': 0.001,
43	  'g|mg': 1000,
44	};
45	
46	/** True se o par (unidade do item, unidade de compra) é convertível automaticamente. */
47	export const ehParPadrao = (unidadeItem?: string | null, unidadeCompra?: string | null): boolean => {
48	  const uf = (unidadeItem ?? '').toLowerCase();
49	  const ui = (unidadeCompra ?? '').toLowerCase();
50	  return uf === ui || `${uf}|${ui}` in RATIOS_PADRAO;
51	};
52	
53	/**
54	 * Fator que converte a quantidade (na unidade do item/produção) para a unidade de
55	 * compra, replicando o banco. Para pares não-padrão usa 1/fator_conversao.
56	 */
57	export const ratioParaUnidadeCompra = (
58	  unidadeItem?: string | null,
59	  unidadeCompra?: string | null,
60	  fatorConversao?: number | null,
61	): number => {
62	  const uf = (unidadeItem ?? '').toLowerCase();
63	  const ui = (unidadeCompra ?? '').toLowerCase();
64	  if (uf === ui) return 1;
65	  const padrao = RATIOS_PADRAO[`${uf}|${ui}`];
66	  if (padrao != null) return padrao;
67	  return fatorConversao && fatorConversao > 0 ? 1 / fatorConversao : 1;
68	};
69	
70	/** Preço por unidade de produção (= preço de compra convertido). Usado em exibições. */
71	export const precoPorUnidadeProducao = (insumo: {
72	  preco_custo: number | null;
73	  unidade_producao?: string | null;
74	  unidade_compra?: string | null;
75	  fator_conversao?: number | null;
76	}): number =>
77	  (Number(insumo.preco_custo) || 0) *
78	  ratioParaUnidadeCompra(insumo.unidade_producao, insumo.unidade_compra, insumo.fator_conversao);
79	
80	/** Custo de uma linha de ingrediente (insumo / sub-receita / esboço). */
81	export const custoItemFicha = (
82	  item: ItemCusto,
83	  insumos: InsumoCusto[],
84	  fichas: CustoFichaRef[] = [],
85	): number => {
86	  if (item.insumo_id) {
87	    const ins = insumos.find((i) => i.id === item.insumo_id);
88	    if (!ins || ins.preco_custo == null) return 0;
89	    const ratio = ratioParaUnidadeCompra(item.unidade, ins.unidade_compra, ins.fator_conversao);
90	    return (Number(ins.preco_custo) || 0) * item.quantidade * ratio;
91	  }
92	  if (item.sub_ficha_id) {
93	    const sub = fichas.find((f) => f.id === item.sub_ficha_id);
94	    if (!sub || sub.rendimento_quantidade <= 0) return 0;
95	    return (sub.custo_calculado / sub.rendimento_quantidade) * item.quantidade;
96	  }
97	  return (item.preco_unitario_esboco ?? 0) * item.quantidade;
98	};
99	
100	/** Custo total dos ingredientes de uma ficha. */
101	export const calcularCustoFicha = (
102	  itens: ItemCusto[],
103	  insumos: InsumoCusto[],
104	  fichas: CustoFichaRef[] = [],
105	): number => itens.reduce((total, item) => total + custoItemFicha(item, insumos, fichas), 0);
