import { supabase } from '@/integrations/supabase/client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';

export type CmvStatus = 'rascunho' | 'aprovada' | 'obsoleta';

export interface CmvFicha {
  id: number;
  nome: string;
  ficha_tecnica_id: number;
  status: CmvStatus;
  custo_calculado: number | null;
  observacoes: string | null;
  created_at: string;
  updated_at: string;
  ficha_nome?: string;
  ficha_custo_calculado?: number;
  ficha_rendimento_quantidade?: number;
  ficha_rendimento_unidade?: string;
}

export interface FichaDisponivel {
  id: number;
  nome: string;
  custo_calculado: number;
  rendimento_quantidade: number;
  rendimento_unidade: string;
}

export function useCmvFichas() {
  const queryClient = useQueryClient();

  const cmvListQuery = useQuery({
    queryKey: ['cmv_fichas'],
    queryFn: async (): Promise<CmvFicha[]> => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .select(`
          *,
          fichas_tecnicas (
            nome,
            custo_calculado,
            rendimento_quantidade,
            rendimento_unidade
          )
        `);

      if (error) {
        throw new Error(error.message);
      }

      type SupabaseResponse = Omit<CmvFicha, 'ficha_nome' | 'ficha_custo_calculado' | 'ficha_rendimento_quantidade' | 'ficha_rendimento_unidade'> & {
        fichas_tecnicas: {
          nome: string;
          custo_calculado: number;
          rendimento_quantidade: number;
          rendimento_unidade: string;
        } | null | undefined;
      };

      return (data as unknown as SupabaseResponse[] || []).map((item) => ({
        id: item.id,
        nome: item.nome,
        ficha_tecnica_id: item.ficha_tecnica_id,
        status: item.status,
        custo_calculado: item.custo_calculado,
        observacoes: item.observacoes,
        created_at: item.created_at,
        updated_at: item.updated_at,
        ficha_nome: item.fichas_tecnicas?.nome,
        ficha_custo_calculado: item.fichas_tecnicas?.custo_calculado,
        ficha_rendimento_quantidade: item.fichas_tecnicas?.rendimento_quantidade,
        ficha_rendimento_unidade: item.fichas_tecnicas?.rendimento_unidade,
      }));
    },
  });

  const availableFichasQuery = useQuery({
    queryKey: ['fichas_aprovadas_sem_cmv'],
    queryFn: async (): Promise<FichaDisponivel[]> => {
      const [fichasRes, cmvRes] = await Promise.all([
        supabase
          .from('fichas_tecnicas')
          .select('id, nome, custo_calculado, rendimento_quantidade, rendimento_unidade')
          .eq('status', 'aprovada'),
        supabase
          .from('cmv_fichas')
          .select('ficha_tecnica_id')
      ]);

      if (fichasRes.error) {
        throw new Error(fichasRes.error.message);
      }
      if (cmvRes.error) {
        throw new Error(cmvRes.error.message);
      }

      const cmvFichasIds = new Set(cmvRes.data?.map(cmv => cmv.ficha_tecnica_id) || []);

      return (fichasRes.data as unknown as FichaDisponivel[] || []).filter(
        (ficha) => !cmvFichasIds.has(ficha.id)
      );
    },
  });

  const createCmv = useMutation({
    mutationFn: async ({ ficha_tecnica_id, nome }: { ficha_tecnica_id: number; nome: string }) => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .insert({ ficha_tecnica_id, nome, status: 'rascunho' as CmvStatus })
        .select()
        .single();

      if (error) {
        throw new Error(error.message);
      }
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
      toast.success('CMV criado com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao criar CMV: ${error.message}`);
    }
  });

  const updateCmvStatus = useMutation({
    mutationFn: async ({ id, status }: { id: number; status: CmvStatus }) => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .update({ status })
        .eq('id', id)
        .select()
        .single();

      if (error) {
        throw new Error(error.message);
      }
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      toast.success('Status do CMV atualizado com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao atualizar status: ${error.message}`);
    }
  });

  const deleteCmv = useMutation({
    mutationFn: async (id: number) => {
      const { error } = await supabase
        .from('cmv_fichas')
        .delete()
        .eq('id', id);

      if (error) {
        throw new Error(error.message);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
      toast.success('CMV excluído com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao excluir CMV: ${error.message}`);
    }
  });

  return {
    cmvList: cmvListQuery.data || [],
    availableFichas: availableFichasQuery.data || [],
    isLoading: cmvListQuery.isLoading || availableFichasQuery.isLoading,
    createCmv,
    updateCmvStatus,
    deleteCmv
  };
}
