import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';

export type CmvNodeKind = 'cmv' | 'ficha' | 'insumo' | 'nf' | 'item';

export interface RawCmv {
  id: number;
  nome: string;
  ficha_tecnica_id: number;
  status: string;
  custo_calculado: number | null;
}

export interface RawCmvFicha {
  id: number;
  nome: string;
  custo_calculado: number | null;
  rendimento_quantidade: number;
  rendimento_unidade: string;
  status: string;
}

export interface RawCmvInsumo {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_compra: string | null;
  unidade_producao: string | null;
  categoria: string | null;
  fornecedor_principal: string | null;
}

export interface RawCmvItem {
  id: number;
  cmv_id: number;
  tipo: string;
  insumo_id: number | null;
  quantidade: number;
  unidade: string;
  preco_unitario_esboco: number | null;
  observacao: string | null;
  custo_calculado: number | null;
  ordem: number;
  insumo?: RawCmvInsumo;
}

export interface RawCmvNF {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
}

export interface RawCmvNFItem {
  id: number;
  nota_id: number;
  insumo_id: number | null;
  nome_produto: string | null;
  valor_unitario: number | null;
  peso_unitario: number | null;
  unidade_base: string | null;
  unidade: string | null;
}

export const cmvNodeId = (id: number) => `cmv_${id}`;
export const fichaNodeId = (id: number) => `ficha_${id}`;
export const insumoNodeId = (id: number) => `insumo_${id}`;
export const nfNodeId = (id: number) => `nf_${id}`;

export const parseNodeId = (key: string): { type: CmvNodeKind; id: number } | null => {
  const parts = key.split('_');
  if (parts.length !== 2) return null;
  const [typeStr, idStr] = parts;
  const id = parseInt(idStr, 10);
  if (isNaN(id)) return null;

  const validTypes: CmvNodeKind[] = ['cmv', 'ficha', 'insumo', 'nf', 'item'];
  if (validTypes.includes(typeStr as CmvNodeKind)) {
    return { type: typeStr as CmvNodeKind, id };
  }
  return null;
};

interface CmvGraphData {
  loading: boolean;
  cmv: RawCmv | null;
  fichaData: RawCmvFicha | null;
  items: RawCmvItem[];
  insumos: RawCmvInsumo[];
  notas: RawCmvNF[];
  nfItems: RawCmvNFItem[];
  positions: Map<string, { x: number; y: number }>;
  savePosition: (key: string, x: number, y: number) => Promise<void>;
  refetch: () => Promise<void>;
}

export function useCmvGraph(cmvId: number | null): CmvGraphData {
  const [loading, setLoading] = useState<boolean>(true);
  const [cmv, setCmv] = useState<RawCmv | null>(null);
  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
  const [items, setItems] = useState<RawCmvItem[]>([]);
  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
  const [notas, setNotas] = useState<RawCmvNF[]>([]);
  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());

  const fetchAll = useCallback(async () => {
    if (cmvId === null) {
      setLoading(false);
      return;
    }

    setLoading(true);

    try {
      const [
        cmvRes,
        itensRes,
        insumosRes,
        posRes,
        nfRes,
        nfItensRes
      ] = await Promise.all([
        supabase.from('cmv_fichas').select('*, fichas_tecnicas(*)').eq('id', cmvId).maybeSingle(),
        supabase.from('cmv_itens').select('*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal)').eq('cmv_id', cmvId).order('ordem'),
        supabase.from('insumos').select('*').eq('ativo', true).order('nome'),
        supabase.from('cmv_canvas_positions').select('*').eq('cmv_id', cmvId),
        supabase.from('notas_fiscais').select('*').order('data_nota', { ascending: false }).limit(80),
        supabase.from('itens_nota_fiscal').select('*').not('insumo_id', 'is', null).limit(2000)
      ]);

      if (cmvRes.data) {
        const rawData = cmvRes.data as Record<string, unknown>;
        setCmv({
          id: rawData.id as number,
          nome: rawData.nome as string,
          ficha_tecnica_id: rawData.ficha_tecnica_id as number,
          status: rawData.status as string,
          custo_calculado: rawData.custo_calculado as number | null
        });

        if (rawData.fichas_tecnicas) {
           const ft = rawData.fichas_tecnicas;
           const ficha = Array.isArray(ft) ? ft[0] : ft;
           if (ficha) {
             const f = ficha as Record<string, unknown>;
             setFichaData({
               id: f.id as number,
               nome: f.nome as string,
               custo_calculado: f.custo_calculado as number | null,
               rendimento_quantidade: f.rendimento_quantidade as number,
               rendimento_unidade: f.rendimento_unidade as string,
               status: f.status as string
             });
           }
        }
      }

      if (itensRes.data) {
        const mappedItems = (itensRes.data as Record<string, unknown>[]).map(item => {
          const insumosData = item.insumos;
          const insumoObj = insumosData ? (Array.isArray(insumosData) ? insumosData[0] : insumosData) : undefined;
          return {
            ...item,
            insumo: insumoObj
          } as unknown as RawCmvItem;
        });
        setItems(mappedItems);
      }

      if (insumosRes.data) {
        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
      }

      if (posRes.data) {
        const newPositions = new Map<string, { x: number; y: number }>();
        for (const pos of (posRes.data as Record<string, unknown>[])) {
          const key = `${pos.node_type}_${pos.node_id}`;
          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
        }
        setPositions(newPositions);
      }

      if (nfRes.data) {
        setNotas(nfRes.data as unknown as RawCmvNF[]);
      }

      if (nfItensRes.data) {
        setNfItems(nfItensRes.data as unknown as RawCmvNFItem[]);
      }

    } catch (err) {
      console.error('Error fetching cmv graph data:', err);
    } finally {
      setLoading(false);
    }
  }, [cmvId]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const savePosition = useCallback(async (key: string, x: number, y: number) => {
    if (cmvId === null) return;

    const parsed = parseNodeId(key);
    if (!parsed) return;

    setPositions(prev => {
      const next = new Map(prev);
      next.set(key, { x, y });
      return next;
    });

    try {
      const { error } = await supabase
        .from('cmv_canvas_positions')
        .upsert(
          { 
            cmv_id: cmvId,
            node_type: parsed.type,
            node_id: parsed.id,
            x,
            y
          },
          { onConflict: 'cmv_id,node_type,node_id' }
        );

      if (error) {
        console.error('Error saving position:', error);
      }
    } catch (err) {
      console.error('Exception saving position:', err);
    }
  }, [cmvId]);

  return {
    loading,
    cmv,
    fichaData,
    items,
    insumos,
    notas,
    nfItems,
    positions,
    savePosition,
    refetch: fetchAll
  };
}
