import { supabase } from '@/integrations/supabase/client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';

export type CmvStatus = 'rascunho' | 'aprovada' | 'obsoleta';

export interface CmvFicha {
  id: number;
  nome: string;
  ficha_tecnica_id: number;
  status: CmvStatus;
  custo_calculado: number | null;
  observacoes: string | null;
  created_at: string;
  updated_at: string;
  ficha_nome?: string;
  ficha_custo_calculado?: number;
  ficha_rendimento_quantidade?: number;
  ficha_rendimento_unidade?: string;
}

export interface FichaDisponivel {
  id: number;
  nome: string;
  custo_calculado: number;
  rendimento_quantidade: number;
  rendimento_unidade: string;
}

export function useCmvFichas() {
  const queryClient = useQueryClient();

  const cmvListQuery = useQuery({
    queryKey: ['cmv_fichas'],
    queryFn: async (): Promise<CmvFicha[]> => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .select(`
          *,
          fichas_tecnicas (
            nome,
            custo_calculado,
            rendimento_quantidade,
            rendimento_unidade
          )
        `);

      if (error) {
        throw new Error(error.message);
      }

      type SupabaseResponse = Omit<CmvFicha, 'ficha_nome' | 'ficha_custo_calculado' | 'ficha_rendimento_quantidade' | 'ficha_rendimento_unidade'> & {
        fichas_tecnicas: {
          nome: string;
          custo_calculado: number;
          rendimento_quantidade: number;
          rendimento_unidade: string;
        } | null | undefined;
      };

      return (data as unknown as SupabaseResponse[] || []).map((item) => ({
        id: item.id,
        nome: item.nome,
        ficha_tecnica_id: item.ficha_tecnica_id,
        status: item.status,
        custo_calculado: item.custo_calculado,
        observacoes: item.observacoes,
        created_at: item.created_at,
        updated_at: item.updated_at,
        ficha_nome: item.fichas_tecnicas?.nome,
        ficha_custo_calculado: item.fichas_tecnicas?.custo_calculado,
        ficha_rendimento_quantidade: item.fichas_tecnicas?.rendimento_quantidade,
        ficha_rendimento_unidade: item.fichas_tecnicas?.rendimento_unidade,
      }));
    },
  });

  const availableFichasQuery = useQuery({
    queryKey: ['fichas_aprovadas_sem_cmv'],
    queryFn: async (): Promise<FichaDisponivel[]> => {
      const [fichasRes, cmvRes] = await Promise.all([
        supabase
          .from('fichas_tecnicas')
          .select('id, nome, custo_calculado, rendimento_quantidade, rendimento_unidade')
          .eq('status', 'aprovada'),
        supabase
          .from('cmv_fichas')
          .select('ficha_tecnica_id'),
      ]);

      if (fichasRes.error) {
        throw new Error(fichasRes.error.message);
      }
      if (cmvRes.error) {
        throw new Error(cmvRes.error.message);
      }

      const cmvFichasIds = new Set(cmvRes.data?.map((cmv) => cmv.ficha_tecnica_id) ?? []);

      return (fichasRes.data as unknown as FichaDisponivel[] || []).filter(
        (ficha) => !cmvFichasIds.has(ficha.id),
      );
    },
  });

  const createCmv = useMutation({
    mutationFn: async ({ ficha_tecnica_id, nome }: { ficha_tecnica_id: number; nome: string }) => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .insert({ ficha_tecnica_id, nome, status: 'rascunho' as CmvStatus })
        .select()
        .single();

      if (error) {
        throw new Error(error.message);
      }
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
      toast.success('CMV criado com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao criar CMV: ${error.message}`);
    },
  });

  const updateCmvStatus = useMutation({
    mutationFn: async ({ id, status }: { id: number; status: CmvStatus }) => {
      const { data, error } = await supabase
        .from('cmv_fichas')
        .update({ status })
        .eq('id', id)
        .select()
        .single();

      if (error) {
        throw new Error(error.message);
      }
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      toast.success('Status do CMV atualizado com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao atualizar status: ${error.message}`);
    },
  });

  const deleteCmv = useMutation({
    mutationFn: async (id: number) => {
      const { error } = await supabase
        .from('cmv_fichas')
        .delete()
        .eq('id', id);

      if (error) {
        throw new Error(error.message);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
      queryClient.invalidateQueries({ queryKey: ['fichas_aprovadas_sem_cmv'] });
      toast.success('CMV excluído com sucesso!');
    },
    onError: (error: Error) => {
      toast.error(`Erro ao excluir CMV: ${error.message}`);
    },
  });

  return {
    cmvList: cmvListQuery.data ?? [],
    availableFichas: availableFichasQuery.data ?? [],
    isLoading: cmvListQuery.isLoading || availableFichasQuery.isLoading,
    createCmv,
    updateCmvStatus,
    deleteCmv,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';

export type CmvNodeKind = 'cmv' | 'ficha' | 'insumo' | 'nf' | 'item';

export interface RawCmv {
  id: number;
  nome: string;
  ficha_tecnica_id: number;
  status: string;
  custo_calculado: number | null;
}

export interface RawCmvFicha {
  id: number;
  nome: string;
  custo_calculado: number | null;
  rendimento_quantidade: number;
  rendimento_unidade: string;
  status: string;
}

export interface RawCmvInsumo {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_compra: string | null;
  unidade_producao: string | null;
  categoria: string | null;
  fornecedor_principal: string | null;
}

export interface RawCmvItem {
  id: number;
  cmv_id: number;
  tipo: string;
  insumo_id: number | null;
  quantidade: number;
  unidade: string;
  preco_unitario_esboco: number | null;
  observacao: string | null;
  custo_calculado: number | null;
  ordem: number;
  insumo?: RawCmvInsumo;
}

export interface RawCmvNF {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
}

export interface RawCmvNFItem {
  id: number;
  nota_id: number;
  insumo_id: number | null;
  nome_produto: string | null;
  valor_unitario: number | null;
  peso_unitario: number | null;
  unidade_base: string | null;
  unidade: string | null;
}

export const cmvNodeId = (id: number) => `cmv_${id}`;
export const fichaNodeId = (id: number) => `ficha_${id}`;
export const insumoNodeId = (id: number) => `insumo_${id}`;
export const nfNodeId = (id: number) => `nf_${id}`;

export const parseNodeId = (key: string): { type: CmvNodeKind; id: number } | null => {
  const idx = key.indexOf('_');
  if (idx < 0) return null;
  const typeStr = key.slice(0, idx);
  const id = Number(key.slice(idx + 1));
  if (!Number.isFinite(id)) return null;
  const validTypes: CmvNodeKind[] = ['cmv', 'ficha', 'insumo', 'nf', 'item'];
  if (validTypes.includes(typeStr as CmvNodeKind)) {
    return { type: typeStr as CmvNodeKind, id };
  }
  return null;
};

interface CmvGraphData {
  loading: boolean;
  cmv: RawCmv | null;
  fichaData: RawCmvFicha | null;
  items: RawCmvItem[];
  insumos: RawCmvInsumo[];
  notas: RawCmvNF[];
  nfItems: RawCmvNFItem[];
  positions: Map<string, { x: number; y: number }>;
  savePosition: (key: string, x: number, y: number) => Promise<void>;
  refetch: () => Promise<void>;
}

export function useCmvGraph(cmvId: number | null): CmvGraphData {
  const [loading, setLoading] = useState<boolean>(true);
  const [cmv, setCmv] = useState<RawCmv | null>(null);
  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
  const [items, setItems] = useState<RawCmvItem[]>([]);
  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
  const [notas, setNotas] = useState<RawCmvNF[]>([]);
  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());

  const fetchAll = useCallback(async () => {
    if (cmvId === null) {
      setLoading(false);
      return;
    }

    setLoading(true);

    try {
      const [
        cmvRes,
        itensRes,
        insumosRes,
        posRes,
        nfRes,
        nfItensRes,
      ] = await Promise.all([
        supabase
          .from('cmv_fichas')
          .select('*, fichas_tecnicas(*)')
          .eq('id', cmvId)
          .maybeSingle(),
        supabase
          .from('cmv_itens')
          .select('*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal)')
          .eq('cmv_id', cmvId)
          .order('ordem'),
        supabase
          .from('insumos')
          .select('id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal')
          .eq('ativo', true)
          .order('nome'),
        supabase
          .from('cmv_canvas_positions')
          .select('*')
          .eq('cmv_id', cmvId),
        supabase
          .from('notas_fiscais')
          .select('id,fornecedor,numero_nota,valor_total,data_nota')
          .order('data_nota', { ascending: false })
          .limit(80),
        supabase
          .from('itens_nota_fiscal')
          .select('id,nota_id,insumo_id,nome_produto,valor_unitario,peso_unitario,unidade_base,unidade')
          .not('insumo_id', 'is', null)
          .limit(2000),
      ]);

      if (cmvRes.data) {
        const raw = cmvRes.data as Record<string, unknown>;
        setCmv({
          id: raw.id as number,
          nome: raw.nome as string,
          ficha_tecnica_id: raw.ficha_tecnica_id as number,
          status: raw.status as string,
          custo_calculado: raw.custo_calculado as number | null,
        });

        if (raw.fichas_tecnicas) {
          const ft = raw.fichas_tecnicas;
          const ficha = Array.isArray(ft) ? ft[0] : ft;
          if (ficha) {
            const f = ficha as Record<string, unknown>;
            setFichaData({
              id: f.id as number,
              nome: f.nome as string,
              custo_calculado: f.custo_calculado as number | null,
              rendimento_quantidade: f.rendimento_quantidade as number,
              rendimento_unidade: f.rendimento_unidade as string,
              status: f.status as string,
            });
          }
        }
      } else {
        setCmv(null);
        setFichaData(null);
      }

      if (itensRes.data) {
        const mappedItems = (itensRes.data as Record<string, unknown>[]).map((item) => {
          const insumosData = item.insumos;
          const insumoObj = insumosData
            ? Array.isArray(insumosData)
              ? insumosData[0]
              : insumosData
            : undefined;
          const mapped: RawCmvItem = {
            id: item.id as number,
            cmv_id: item.cmv_id as number,
            tipo: item.tipo as string,
            insumo_id: item.insumo_id as number | null,
            quantidade: item.quantidade as number,
            unidade: item.unidade as string,
            preco_unitario_esboco: item.preco_unitario_esboco as number | null,
            observacao: item.observacao as string | null,
            custo_calculado: item.custo_calculado as number | null,
            ordem: item.ordem as number,
            insumo: insumoObj as RawCmvInsumo | undefined,
          };
          return mapped;
        });
        setItems(mappedItems);
      } else {
        setItems([]);
      }

      if (insumosRes.data) {
        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
      }

      if (posRes.data) {
        const newPositions = new Map<string, { x: number; y: number }>();
        for (const pos of posRes.data as Record<string, unknown>[]) {
          const key = `${pos.node_type}_${pos.node_id}`;
          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
        }
        setPositions(newPositions);
      } else {
        setPositions(new Map());
      }

      if (nfRes.data) {
        setNotas(nfRes.data as unknown as RawCmvNF[]);
      }

      if (nfItensRes.data) {
        setNfItems(nfItensRes.data as unknown as RawCmvNFItem[]);
      }
    } catch (err) {
      console.error('[useCmvGraph] fetchAll error:', err);
    } finally {
      setLoading(false);
    }
  }, [cmvId]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const savePosition = useCallback(
    async (key: string, x: number, y: number) => {
      if (cmvId === null) return;

      const parsed = parseNodeId(key);
      if (!parsed) return;

      // Update local state optimistically
      setPositions((prev) => {
        const next = new Map(prev);
        next.set(key, { x, y });
        return next;
      });

      try {
        const { error } = await supabase
          .from('cmv_canvas_positions')
          .upsert(
            {
              cmv_id: cmvId,
              node_type: parsed.type,
              node_id: parsed.id,
              x,
              y,
            },
            { onConflict: 'cmv_id,node_type,node_id' },
          );

        if (error) {
          console.error('[useCmvGraph] savePosition error:', error);
        }
      } catch (err) {
        console.error('[useCmvGraph] savePosition exception:', err);
      }
    },
    [cmvId],
  );

  return {
    loading,
    cmv,
    fichaData,
    items,
    insumos,
    notas,
    nfItems,
    positions,
    savePosition,
    refetch: fetchAll,
  };
}

