  const [deleteId, setDeleteId] = useState<string | null>(null)

  const filteredCmvs = useMemo(() => {
    return cmvs.filter(cmv => {
      const matchBusca = cmv.nome.toLowerCase().includes(busca.toLowerCase()) || 
                         (cmv.ficha_nome || '').toLowerCase().includes(busca.toLowerCase())
      const matchStatus = statusFiltro === 'todos' || cmv.status === statusFiltro
      return matchBusca && matchStatus
    })
  }, [cmvs, busca, statusFiltro])

  const handleCreate = async () => {
    if (!selectedFichaId || !newCmvNome.trim()) {
      toast.error('Preencha os campos obrigatórios')
      return
    }
    try {
      const newCmv = await createCmv.mutateAsync({
        ficha_tecnica_id: selectedFichaId,
        nome: newCmvNome.trim()
      })
      toast.success('CMV criado com sucesso')
      setIsNewDialogOpen(false)
      navigate(`/financeiro/cmv/configurador?focus=${newCmv.id}`)
    } catch (err) {
      toast.error('Erro ao criar CMV')
    }
  }

  const handleDelete = async () => {
    if (!deleteId) return
    try {
      await deleteCmv.mutateAsync(deleteId)
      toast.success('CMV excluído')
    } catch (err) {
      toast.error('Erro ao excluir CMV')
    } finally {
      setDeleteId(null)
    }
  }

  const handleUpdateStatus = async (id: string, status: CmvStatus) => {
    try {
      await updateCmvStatus.mutateAsync({ id, status })
      toast.success(`Status atualizado para ${status}`)
    } catch (err) {
      toast.error('Erro ao atualizar status')
    }
  }

  const handleFichaSelect = (fichaId: string) => {
    setSelectedFichaId(fichaId)
    const ficha = availableFichas.find(f => f.id === fichaId)
    if (ficha && !newCmvNome) {
      setNewCmvNome(`CMV - ${ficha.nome}`)
    }
  }

  return (
    <div className="min-h-screen bg-white dark:bg-[#0A0A0A] relative overflow-hidden flex flex-col">
      {/* Awning Stripe */}
      <div className="h-1.5 w-full bg-[repeating-linear-gradient(45deg,#57715B,#57715B_10px,transparent_10px,transparent_20px)] opacity-20" />

      {/* Ambient Glows */}
      <div className="fixed top-0 left-0 w-[500px] h-[500px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none -translate-x-1/2 -translate-y-1/2" />
      <div className="fixed bottom-0 right-0 w-[400px] h-[400px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none translate-x-1/3 translate-y-1/3" />

      {/* Animated Watermark */}
      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.03] pointer-events-none animate-pulse duration-[10000ms]">
        <Calculator size={400} />
      </div>

      <div className="relative flex-1 container mx-auto p-4 sm:p-6 max-w-7xl">
        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-[#57715B]/10 rounded-2xl">
              <Calculator className="w-6 h-6 text-[#57715B]" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-zinc-900 dark:text-zinc-100">CMV</h1>
              <p className="text-sm text-zinc-500 dark:text-zinc-400">Custo de Mercadoria Vendida</p>
            </div>
          </div>

          <Button 
            className="bg-[#57715B] text-white hover:bg-[#57715B]/90 shadow-sm"
            onClick={() => {
              setNewCmvNome('')
              setSelectedFichaId('')
              setIsNewDialogOpen(true)
            }}
          >
            <Plus className="w-4 h-4 mr-2" />
            Novo CMV
          </Button>
        </header>

        <div className="flex flex-col sm:flex-row gap-3 mb-6">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-400" />
            <Input 
              placeholder="Buscar CMV ou ficha..." 
              value={busca}
              onChange={e => setBusca(e.target.value)}
              className="pl-9 bg-white/50 dark:bg-zinc-900/50 backdrop-blur-sm border-zinc-200 dark:border-zinc-800 focus-visible:ring-[#57715B]"
            />
          </div>
          <Select value={statusFiltro} onValueChange={(val: string) => setStatusFiltro(val as CmvStatus | 'todos')}>
            <SelectTrigger className="w-full sm:w-[180px] bg-white/50 dark:bg-zinc-900/50 backdrop-blur-sm border-zinc-200 dark:border-zinc-800">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="todos">Todos os status</SelectItem>
              <SelectItem value="rascunho">Rascunho</SelectItem>
              <SelectItem value="aprovada">Aprovada</SelectItem>
              <SelectItem value="obsoleta">Obsoleta</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-20">
            <Calculator className="w-8 h-8 text-[#57715B] animate-spin opacity-50" />
          </div>
        ) : filteredCmvs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 px-4 text-center border border-dashed border-zinc-200 dark:border-zinc-800 rounded-3xl bg-white/30 dark:bg-zinc-900/20 backdrop-blur-sm">
            <div className="p-4 bg-[#57715B]/10 rounded-full mb-4">
              <Calculator className="w-8 h-8 text-[#57715B]" />
            </div>
            <h3 className="text-lg font-medium text-zinc-900 dark:text-zinc-100 mb-2">Nenhum CMV encontrado</h3>
            <p className="text-zinc-500 max-w-sm mb-6">Você ainda não possui nenhum CMV cadastrado com os filtros atuais.</p>
            <Button 
              variant="outline" 
              className="border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/5"
              onClick={() => {
                setBusca('')
                setStatusFiltro('todos')
              }}
            >
              Limpar filtros
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
            {filteredCmvs.map(cmv => {
              const statusConf = STATUS_CONFIG[cmv.status]
              const StatusIcon = statusConf.icon

              const rendimento = cmv.ficha_rendimento_quantidade || 1
              const custoFichaTotal = cmv.ficha_custo_calculado || 0
              const unitarioFicha = custoFichaTotal / rendimento
              const custoTotal = cmv.custo_calculado || 0
              const extras = Math.max(0, custoTotal - unitarioFicha)

              return (
                <div 
                  key={cmv.id}
                  className="group relative flex flex-col rounded-2xl border border-white/30 dark:border-zinc-800/50 bg-white/60 dark:bg-zinc-900/40 backdrop-blur-xl shadow-sm hover:shadow-xl hover:-translate-y-1 p-5 transition-all duration-300"
                >
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex-1 pr-4">
                      <h3 className="font-semibold text-zinc-900 dark:text-zinc-100 text-lg leading-tight truncate" title={cmv.nome}>
                        {cmv.nome}
                      </h3>
                      {cmv.ficha_nome && (
                        <div className="flex items-center gap-1.5 mt-1.5 text-sm text-zinc-500">
                          <Workflow className="w-3.5 h-3.5 shrink-0" />
                          <span className="truncate" title={cmv.ficha_nome}>{cmv.ficha_nome}</span>
                        </div>
                      )}
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-8 w-8 -mr-2 text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300 transition-colors">
                          <ChevronDown className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-48">
                        <DropdownMenuItem onClick={() => navigate(`/financeiro/cmv/configurador?focus=${cmv.id}`)}>
                          <Workflow className="w-4 h-4 mr-2" /> Abrir no Construtor
                        </DropdownMenuItem>
                        {cmv.status === 'rascunho' && (
                          <DropdownMenuItem onClick={() => handleUpdateStatus(cmv.id, 'aprovada')}>
                            <CheckCircle2 className="w-4 h-4 mr-2" /> Aprovar
                          </DropdownMenuItem>
                        )}
                        {cmv.status !== 'obsoleta' && (
                          <DropdownMenuItem onClick={() => handleUpdateStatus(cmv.id, 'obsoleta')}>
                            <Archive className="w-4 h-4 mr-2" /> Marcar obsoleta
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem className="text-red-600 focus:text-red-600 focus:bg-red-50 dark:focus:bg-red-950/30" onClick={() => setDeleteId(cmv.id)}>
                          <Trash2 className="w-4 h-4 mr-2" /> Excluir
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>

                  <div className="mb-auto">
                    <Badge variant="secondary" className={cn("mb-4 font-medium", statusConf.className)}>
                      <StatusIcon className="w-3 h-3 mr-1.5" />
                      {statusConf.label}
                    </Badge>
                  </div>

                  <div className="pt-4 mt-2 border-t border-zinc-100 dark:border-zinc-800">
                    <div className="flex items-end justify-between">
                      <div>
                        <p className="text-xs font-medium text-zinc-500 uppercase tracking-wider mb-1">Custo Total</p>
                        <p className="text-xl font-bold text-emerald-600 dark:text-emerald-500">
                          {fmt(custoTotal)}
                        </p>
                      </div>
                      <div className="text-right flex flex-col items-end gap-1">
                        <div className="text-xs text-zinc-500 bg-zinc-100 dark:bg-zinc-800/50 px-2 py-0.5 rounded-md">
                          Produção: <span className="font-medium text-zinc-700 dark:text-zinc-300">{fmt(unitarioFicha)}</span>
                        </div>
                        <div className="text-xs text-zinc-500 bg-zinc-100 dark:bg-zinc-800/50 px-2 py-0.5 rounded-md">
                          Extras: <span className="font-medium text-zinc-700 dark:text-zinc-300">{fmt(extras)}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      <Dialog open={isNewDialogOpen} onOpenChange={setIsNewDialogOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Novo CMV</DialogTitle>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <label className="text-sm font-medium">Ficha Técnica Base</label>
              {availableFichas.length === 0 ? (
                <div className="text-sm text-amber-600 dark:text-amber-500 bg-amber-50 dark:bg-amber-950/30 p-3 rounded-lg border border-amber-200/50 dark:border-amber-900/50 flex items-center gap-2">
                  <Archive className="w-4 h-4 shrink-0" />
                  Todas as fichas aprovadas já possuem CMV.
                </div>
              ) : (
                <Select value={selectedFichaId} onValueChange={handleFichaSelect}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione uma ficha..." />
                  </SelectTrigger>
                  <SelectContent>
                    {availableFichas.map(f => (
                      <SelectItem key={f.id} value={f.id}>
                        {f.nome} (Rende {f.rendimento_quantidade} {f.rendimento_unidade})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="grid gap-2">
              <label className="text-sm font-medium">Nome do CMV</label>
              <Input 
                placeholder="Ex: CMV - Hambúrguer Clássico"
                value={newCmvNome}
                onChange={e => setNewCmvNome(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" onClick={() => setIsNewDialogOpen(false)}>Cancelar</Button>
            <Button 
              className="bg-[#57715B] text-white hover:bg-[#57715B]/90" 
              onClick={handleCreate}
              disabled={!selectedFichaId || !newCmvNome.trim() || createCmv?.isPending}
            >
              {createCmv?.isPending ? 'Salvando...' : 'Salvar e Configurar'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open: boolean) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir CMV</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja excluir este CMV? Esta ação não pode ser desfeita e removerá todas as configurações de custos extras atreladas.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction 
              onClick={handleDelete}
              className="bg-red-600 hover:bg-red-700 text-white focus:ring-red-600"
            >
              {deleteCmv?.isPending ? 'Excluindo...' : 'Excluir'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
