import { memo, useCallback, useEffect, useMemo, useState } from 'react';
import {
  ReactFlow,
  ReactFlowProvider,
  Background,
  BackgroundVariant,
  MiniMap,
  Panel,
  useNodesState,
  useEdgesState,
  useReactFlow,
  Handle,
  Position,
  type Node,
  type Edge,
  type NodeTypes,
  type NodeDragHandler,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';
import {
  useCmvGraph,
  cmvNodeId,
  fichaNodeId,
  insumoNodeId,
  nfNodeId,
  type RawCmvItem,
} from '@/features/financeiro/model/useCmvGraph';
import { layoutGraph } from '@/components/producao/configurador/layout';
import { toast } from 'sonner';
import {
  ArrowLeft,
  LayoutTemplate,
  Plus,
  Save,
  Trash2,
  Package,
  Truck,
  Zap,
  FileText,
  Loader2,
  Calculator,
  ChefHat,
  Wheat,
  Receipt,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetFooter,
} from '@/shared/ui/sheet';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/shared/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';

// ---------------------------------------------------------------------------
// HELPERS
// ---------------------------------------------------------------------------

const fmt = (v: number | null | undefined): string => {
  if (typeof v !== 'number') return 'R$ 0,00';
  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

type TipoItem = 'embalagem' | 'frete' | 'overhead' | 'nf_linked';

const TIPO_CONFIG: Record<TipoItem, { label: string; color: string; icon: React.ReactNode }> = {
  embalagem: { label: 'Embalagem', color: 'bg-blue-600/80 border-blue-400/40', icon: <Package size={12} /> },
  frete: { label: 'Frete', color: 'bg-orange-600/80 border-orange-400/40', icon: <Truck size={12} /> },
  overhead: { label: 'Overhead', color: 'bg-purple-600/80 border-purple-400/40', icon: <Zap size={12} /> },
  nf_linked: { label: 'NF Vinculada', color: 'bg-cyan-600/80 border-cyan-400/40', icon: <FileText size={12} /> },
};

const STATUS_COLORS: Record<string, string> = {
  rascunho: 'bg-zinc-700 text-zinc-300',
  aprovada: 'bg-emerald-800 text-emerald-300',
  obsoleta: 'bg-zinc-800 text-zinc-500',
};

// ---------------------------------------------------------------------------
// CUSTOM NODE COMPONENTS
// ---------------------------------------------------------------------------

interface CmvRootNodeData {
  nome: string;
  custo: number | null;
  status: string;
}

const CmvRootNode = memo(function CmvRootNode({ data }: { data: CmvRootNodeData }) {
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
      <div className="flex items-start justify-between mb-2 gap-2">
        <div className="flex items-center gap-1.5 opacity-80">
          <Calculator size={12} />
          <span className="text-[9px] font-bold uppercase tracking-wider">CMV Central</span>
        </div>
        <span className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}>
          {data.status}
        </span>
      </div>
      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
      <Handle type="target" position={Position.Left} className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30" />
    </div>
  );
});

interface FichaBaseNodeData {
  nome: string;
  custoUnitario: number;
  rendimento: string;
  status: string;
}

const FichaBaseNode = memo(function FichaBaseNode({ data }: { data: FichaBaseNodeData }) {
  return (
    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
      <div className="flex items-center gap-1.5 opacity-80 mb-2">
        <ChefHat size={12} />
        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
      </div>
      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
      <div className="flex items-end justify-between mt-2">
        <div>
          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo unitário</p>
          <p className="text-xl font-bold tabular-nums">{fmt(data.custoUnitario)}</p>
        </div>
        <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full">{data.rendimento}</span>
      </div>
      <Handle type="source" position={Position.Right} className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white" />
    </div>
  );
});

interface CmvItemNodeData {
  tipo: TipoItem;
  quantidade: number;
  unidade: string;
  custo: number | null;
  label: string;
}

const CmvItemNode = memo(function CmvItemNode({ data, selected }: { data: CmvItemNodeData; selected: boolean }) {
  const cfg = TIPO_CONFIG[data.tipo] ?? TIPO_CONFIG.overhead;
  return (
    <div className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${cfg.color} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}>
      <div className="flex items-center gap-1.5 mb-2">
        <span className="opacity-80">{cfg.icon}</span>
        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{cfg.label}</span>
      </div>
      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
      <div className="flex items-end justify-between">
        <span className="text-[11px] text-white/70">{data.quantidade} {data.unidade}</span>
        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
      </div>
      <Handle type="target" position={Position.Left} className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20" />
      <Handle type="source" position={Position.Right} className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30" />
    </div>
  );
});

interface InsumoNodeData {
  nome: string;
  preco: number | null;
  unidade: string;
}

const InsumoNode = memo(function InsumoNode({ data }: { data: InsumoNodeData }) {
  return (
    <div className="px-3 py-2 rounded-lg border border-violet-400/30 bg-violet-700/70 backdrop-blur-sm text-white min-w-[180px] shadow-md">
      <div className="flex items-center gap-1 mb-1 opacity-70">
        <Wheat size={10} />
        <span className="text-[9px] font-bold uppercase">Insumo</span>
      </div>
      <h4 className="text-xs font-semibold truncate">{data.nome}</h4>
      <p className="text-sm font-bold tabular-nums">
        {fmt(data.preco)} <span className="text-[9px] font-normal opacity-60">/{data.unidade}</span>
      </p>
      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-violet-300 !border-2 !border-white" />
    </div>
  );
});

interface NFNodeData {
  fornecedor: string;
  numero: string | null;
  valor: number | null;
}

const NFNode = memo(function NFNode({ data }: { data: NFNodeData }) {
  return (
    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
      <div className="flex items-center gap-1 mb-1 opacity-70">
        <Receipt size={10} />
        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
      </div>
      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor || 'Fornecedor'}</h4>
      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
      <p className="text-xs font-bold tabular-nums">{fmt(data.valor)}</p>
      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white" />
    </div>
  );
});

const nodeTypes: NodeTypes = {
  cmv: CmvRootNode as unknown as NodeTypes['string'],
  ficha: FichaBaseNode as unknown as NodeTypes['string'],
  cmvItem: CmvItemNode as unknown as NodeTypes['string'],
  insumo: InsumoNode as unknown as NodeTypes['string'],
  nf: NFNode as unknown as NodeTypes['string'],
};

// ---------------------------------------------------------------------------
// INNER COMPONENT (usa useReactFlow())
// ---------------------------------------------------------------------------

function CmvConfiguratorInner() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cmvIdParam = searchParams.get('focus');
  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;

  const {
    loading,
    cmv,
    fichaData,
    items,
    insumos,
    positions,
    savePosition,
    refetch,
  } = useCmvGraph(cmvId);

  const { fitView } = useReactFlow();
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // Detail panel state
  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Add item dialog state
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
  const [newQty, setNewQty] = useState('1');
  const [newUnit, setNewUnit] = useState('un');
  const [newPreco, setNewPreco] = useState('');
  const [newObs, setNewObs] = useState('');
  const [isAddSaving, setIsAddSaving] = useState(false);

  // -------------------------------------------------------------------------
  // Build ReactFlow nodes/edges from hook data
  // -------------------------------------------------------------------------
  const buildGraph = useCallback(() => {
    if (!cmv) return;

    const newNodes: Node[] = [];
    const newEdges: Edge[] = [];

    const rootId = cmvNodeId(cmv.id);

    // Root node
    newNodes.push({
      id: rootId,
      type: 'cmv',
      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
      position: positions.get(rootId) ?? { x: 800, y: 300 },
    });

    // Ficha base node
    if (fichaData) {
      const fId = fichaNodeId(fichaData.id);
      const rendQty = fichaData.rendimento_quantidade || 1;
      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;

      newNodes.push({
        id: fId,
        type: 'ficha',
        data: {
          nome: fichaData.nome,
          custoUnitario,
          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
          status: fichaData.status,
          kind: 'ficha',
        } as Record<string, unknown>,
        position: positions.get(fId) ?? { x: 400, y: 300 },
      });

      newEdges.push({
        id: `e-${fId}-${rootId}`,
        source: fId,
        target: rootId,
        animated: true,
        style: { stroke: '#F59E0B', strokeWidth: 3 },
      });
    }

    // Item nodes
    const addedInsumoIds = new Set<number>();

    items.forEach((item, idx) => {
      const itemId = `item_${item.id}`;
      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;

      newNodes.push({
        id: itemId,
        type: 'cmvItem',
        data: {
          tipo: item.tipo as TipoItem,
          quantidade: item.quantidade,
          unidade: item.unidade,
          custo: item.custo_calculado,
          label,
          kind: 'cmvItem',
          _rawItemId: item.id,
        } as Record<string, unknown>,
        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
      });

      newEdges.push({
        id: `e-${itemId}-${rootId}`,
        source: itemId,
        target: rootId,
        style: { stroke: '#52525b', strokeWidth: 2 },
      });

      // Insumo linked to item
      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
        addedInsumoIds.add(item.insumo_id);
        const insId = insumoNodeId(item.insumo_id);
        const insData = insumos.find((i) => i.id === item.insumo_id);

        newNodes.push({
          id: insId,
          type: 'insumo',
          data: {
            nome: insData?.nome ?? 'Insumo',
            preco: insData?.preco_custo ?? null,
            unidade: insData?.unidade_compra ?? 'un',
            kind: 'insumo',
          } as Record<string, unknown>,
          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
        });

        newEdges.push({
          id: `e-${insId}-${itemId}`,
          source: insId,
          target: itemId,
          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
        });
      }
    });

    // Apply dagre layout for nodes without saved positions
    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
    if (!hasAllPositions && newNodes.length > 0) {
      const laid = layoutGraph(newNodes, newEdges, 'LR');
      setNodes(laid);
    } else {
      setNodes(newNodes);
    }
    setEdges(newEdges);

    setTimeout(() => {
      fitView({ padding: 0.12, duration: 400 });
    }, 80);
  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);

  useEffect(() => {
    if (!loading) {
      buildGraph();
    }
  }, [loading, buildGraph]);

  // -------------------------------------------------------------------------
  // Node drag → save position
  // -------------------------------------------------------------------------
  const handleNodeDragStop: NodeDragHandler = useCallback(
    (_evt, node) => {
      savePosition(node.id, node.position.x, node.position.y);
    },
    [savePosition],
  );

  // -------------------------------------------------------------------------
  // Node click → open detail panel
  // -------------------------------------------------------------------------
  const handleNodeClick = useCallback(
    (_evt: React.MouseEvent, node: Node) => {
      const rawId = (node.data as Record<string, unknown>)._rawItemId;
      if (typeof rawId !== 'number') {
        setSelectedItemData(null);
        return;
      }
      const found = items.find((it) => it.id === rawId);
      if (found) {
        setSelectedItemData(found);
        setEditQty(String(found.quantidade));
        setEditUnit(found.unidade);
        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
        setEditObs(found.observacao ?? '');
      }
    },
    [items],
  );

  // -------------------------------------------------------------------------
  // Auto-layout
  // -------------------------------------------------------------------------
  const handleAutoLayout = useCallback(() => {
    setNodes((prev) => {
      const laid = layoutGraph(prev, edges, 'LR');
      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
      return laid;
    });
    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
  }, [edges, fitView, savePosition, setNodes]);

  // -------------------------------------------------------------------------
  // Save item
  // -------------------------------------------------------------------------
  const handleSaveItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsSaving(true);
    const { error } = await supabase
      .from('cmv_itens')
      .update({
        quantidade: parseFloat(editQty) || selectedItemData.quantidade,
        unidade: editUnit,
        preco_unitario_esboco: editPreco !== '' ? parseFloat(editPreco) : null,
        observacao: editObs || null,
      })
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } else {
      toast.success('Item atualizado!');
      setSelectedItemData(null);
      await refetch();
    }
    setIsSaving(false);
  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch]);

  // -------------------------------------------------------------------------
  // Delete item
  // -------------------------------------------------------------------------
  const handleDeleteItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsDeleting(true);
    const { error } = await supabase
      .from('cmv_itens')
      .delete()
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao excluir: ${error.message}`);
    } else {
      toast.success('Item removido!');
      setSelectedItemData(null);
      await refetch();
    }
    setIsDeleting(false);
  }, [selectedItemData, refetch]);

  // -------------------------------------------------------------------------
  // Add item
  // -------------------------------------------------------------------------
  const handleAddItem = useCallback(async () => {
    if (!cmvId) return;
    setIsAddSaving(true);
    const { error } = await supabase.from('cmv_itens').insert({
      cmv_id: cmvId,
      tipo: newTipo,
      quantidade: parseFloat(newQty) || 1,
      unidade: newUnit,
      preco_unitario_esboco: newPreco !== '' ? parseFloat(newPreco) : null,
      observacao: newObs || null,
      ordem: items.length,
    });

    if (error) {
      toast.error(`Erro ao criar item: ${error.message}`);
    } else {
      toast.success('Item adicionado!');
      setIsAddOpen(false);
      setNewTipo('embalagem');
      setNewQty('1');
      setNewUnit('un');
      setNewPreco('');
      setNewObs('');
      await refetch();
    }
    setIsAddSaving(false);
  }, [cmvId, newTipo, newQty, newUnit, newPreco, newObs, items.length, refetch]);

  // -------------------------------------------------------------------------
  // Empty/loading states
  // -------------------------------------------------------------------------
  if (!cmvId) {
    return (
      <div className="h-screen bg-[#0F1117] flex flex-col items-center justify-center text-zinc-400">
        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar ao CMV
        </Button>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="h-screen bg-[#0F1117] flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
      </div>
    );
  }

  if (!cmv) {
    return (
      <div className="h-screen bg-[#0F1117] flex flex-col items-center justify-center text-zinc-400">
        <p className="text-sm mb-4">CMV não encontrado.</p>
        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar
        </Button>
      </div>
    );
  }

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  return (
    <div className="h-screen w-screen bg-[#0F1117] overflow-hidden">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        nodeTypes={nodeTypes}
        onNodeDragStop={handleNodeDragStop}
        onNodeClick={handleNodeClick}
        fitView
        proOptions={{ hideAttribution: true }}
        minZoom={0.2}
        maxZoom={2}
      >
        <Background variant={BackgroundVariant.Dots} color="#1e2028" gap={20} />
        <MiniMap
          style={{ background: '#1a1d24', border: '1px solid #2a2d34' }}
          nodeColor={() => '#57715B'}
          maskColor="rgba(0,0,0,0.6)"
        />

        {/* Toolbar topo esquerdo */}
        <Panel position="top-left">
          <div className="flex items-center gap-2 bg-zinc-900/90 border border-zinc-700/50 backdrop-blur-md rounded-xl px-3 py-2 shadow-xl">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 text-zinc-400 hover:text-white"
              onClick={() => navigate('/financeiro/cmv')}
            >
              <ArrowLeft size={16} />
            </Button>
            <div className="w-px h-5 bg-zinc-700" />
            <div className="flex items-center gap-2">
              <Calculator size={14} className="text-[#57715B]" />
              <span className="text-sm font-semibold text-zinc-200 truncate max-w-[200px]">
                {cmv.nome}
              </span>
              <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[cmv.status] ?? STATUS_COLORS.rascunho}`}>
                {cmv.status}
              </span>
            </div>
            <div className="w-px h-5 bg-zinc-700" />
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs text-zinc-400 hover:text-white gap-1.5"
              onClick={handleAutoLayout}
            >
              <LayoutTemplate size={13} />
              <span className="hidden sm:inline">Auto-layout</span>
            </Button>
            <Button
              size="sm"
              className="h-7 text-xs bg-[#57715B] hover:bg-[#465b49] text-white gap-1.5"
              onClick={() => setIsAddOpen(true)}
            >
              <Plus size={13} />
              <span className="hidden sm:inline">Adicionar</span>
            </Button>
          </div>
        </Panel>

        {/* Legenda top-right */}
        <Panel position="top-right">
          <div className="flex flex-col gap-1.5 bg-zinc-900/80 border border-zinc-700/40 backdrop-blur-md rounded-xl p-3 shadow-lg text-[10px] text-zinc-400">
            {(Object.entries(TIPO_CONFIG) as [TipoItem, typeof TIPO_CONFIG[TipoItem]][]).map(([tipo, cfg]) => (
              <div key={tipo} className="flex items-center gap-1.5">
                <span className="opacity-80">{cfg.icon}</span>
                <span>{cfg.label}</span>
              </div>
            ))}
          </div>
        </Panel>
      </ReactFlow>

      {/* Detail Panel (Sheet) */}
      <Sheet open={!!selectedItemData} onOpenChange={(o) => !o && setSelectedItemData(null)}>
        <SheetContent side="right" className="bg-zinc-950 border-zinc-800 text-zinc-100 w-full sm:max-w-[380px]">
          <SheetHeader className="mb-4">
            <SheetTitle className="text-zinc-100">Editar Item</SheetTitle>
          </SheetHeader>

          {selectedItemData && (
            <div className="space-y-4">
              <div>
                <Label className="text-zinc-400 text-xs">Tipo</Label>
                <p className="text-sm font-semibold mt-1">
                  {TIPO_CONFIG[selectedItemData.tipo as TipoItem]?.label ?? selectedItemData.tipo}
                </p>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-zinc-400 text-xs">Quantidade</Label>
                  <Input
                    type="number"
                    className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                  />
                </div>
                <div>
                  <Label className="text-zinc-400 text-xs">Unidade</Label>
                  <Input
                    className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <Label className="text-zinc-400 text-xs">Preço unitário (esboço)</Label>
                <Input
                  type="number"
                  step="0.01"
                  className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                  placeholder="0,00"
                  value={editPreco}
                  onChange={(e) => setEditPreco(e.target.value)}
                />
              </div>

              <div>
                <Label className="text-zinc-400 text-xs">Observação</Label>
                <Input
                  className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                  placeholder="Observação opcional..."
                  value={editObs}
                  onChange={(e) => setEditObs(e.target.value)}
                />
              </div>

              {selectedItemData.custo_calculado !== null && (
                <div className="pt-2 border-t border-zinc-800">
                  <p className="text-xs text-zinc-500">Custo calculado</p>
                  <p className="text-xl font-bold text-emerald-400 tabular-nums">
                    {fmt(selectedItemData.custo_calculado)}
                  </p>
                </div>
              )}
            </div>
          )}

          <SheetFooter className="mt-6 flex gap-2">
            <Button
              variant="destructive"
              size="sm"
              className="flex-1"
              onClick={handleDeleteItem}
              disabled={isDeleting || isSaving}
            >
              {isDeleting ? <Loader2 size={14} className="animate-spin mr-1" /> : <Trash2 size={14} className="mr-1" />}
              Excluir
            </Button>
            <Button
              size="sm"
              className="flex-1 bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleSaveItem}
              disabled={isSaving || isDeleting}
            >
              {isSaving ? <Loader2 size={14} className="animate-spin mr-1" /> : <Save size={14} className="mr-1" />}
              Salvar
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      {/* Add Item Dialog */}
      <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
        <DialogContent className="bg-zinc-950 border-zinc-800 text-zinc-100">
          <DialogHeader>
            <DialogTitle className="text-zinc-100">Adicionar Item de Custo</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div>
              <Label className="text-zinc-400 text-xs">Tipo de custo</Label>
              <Select value={newTipo} onValueChange={(v) => setNewTipo(v as TipoItem)}>
                <SelectTrigger className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-zinc-900 border-zinc-700">
                  {(Object.entries(TIPO_CONFIG) as [TipoItem, typeof TIPO_CONFIG[TipoItem]][]).map(([tipo, cfg]) => (
                    <SelectItem key={tipo} value={tipo} className="text-zinc-200">
                      <div className="flex items-center gap-1.5">
                        {cfg.icon}
                        {cfg.label}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-zinc-400 text-xs">Quantidade</Label>
                <Input
                  type="number"
                  className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                  value={newQty}
                  onChange={(e) => setNewQty(e.target.value)}
                />
              </div>
              <div>
                <Label className="text-zinc-400 text-xs">Unidade</Label>
                <Input
                  className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                  placeholder="un, kg, cx..."
                  value={newUnit}
                  onChange={(e) => setNewUnit(e.target.value)}
                />
              </div>
            </div>

            <div>
              <Label className="text-zinc-400 text-xs">Preço unitário</Label>
              <Input
                type="number"
                step="0.01"
                className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                placeholder="0,00"
                value={newPreco}
                onChange={(e) => setNewPreco(e.target.value)}
              />
            </div>

            <div>
              <Label className="text-zinc-400 text-xs">Observação</Label>
              <Input
                className="mt-1 bg-zinc-900 border-zinc-700 text-zinc-100"
                placeholder="Observação opcional..."
                value={newObs}
                onChange={(e) => setNewObs(e.target.value)}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" className="border-zinc-700 text-zinc-300" onClick={() => setIsAddOpen(false)}>
              Cancelar
            </Button>
            <Button
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleAddItem}
              disabled={isAddSaving}
            >
              {isAddSaving ? <Loader2 size={14} className="animate-spin mr-1" /> : <Plus size={14} className="mr-1" />}
              Adicionar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

