import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import CmvPage from './Cmv.page';

// Mock do hook de dados
vi.mock('@/features/financeiro/model/useCmvFichas', () => ({
  useCmvFichas: () => ({
    cmvList: [],
    availableFichas: [],
    isLoading: false,
    createCmv: { mutateAsync: vi.fn(), isPending: false },
    updateCmvStatus: { mutate: vi.fn() },
    deleteCmv: { mutateAsync: vi.fn() },
  }),
}));

function renderPage() {
  return render(
    <MemoryRouter>
      <CmvPage />
    </MemoryRouter>,
  );
}

describe('CmvPage', () => {
  it('renderiza o título da página', () => {
    renderPage();
    expect(screen.getByText('CMV')).toBeInTheDocument();
  });

  it('mostra subtítulo Custo de Mercadoria Vendida', () => {
    renderPage();
    expect(screen.getByText(/Custo de Mercadoria Vendida/i)).toBeInTheDocument();
  });

  it('mostra botão Novo CMV', () => {
    renderPage();
    expect(screen.getByRole('button', { name: /Novo CMV/i })).toBeInTheDocument();
  });

  it('mostra estado vazio quando não há CMVs', () => {
    renderPage();
    expect(screen.getByText(/Nenhum CMV cadastrado/i)).toBeInTheDocument();
  });
});

